const VILLAGE_HOUSE_SCALE=1.5;
const villageHouses=[{x:74,z:-29,r:0},{x:86,z:-15,r:Math.PI},{x:74,z:6,r:0},{x:85,z:22,r:Math.PI}];
function inVillage(x,z){return x>65&&z>-36&&z<33;}
const villageCollision=MapManager.prototype.collides;
MapManager.prototype.collides=function(x,z,r=.42){for(const h of villageHouses){const sign=h.r?-1:1,s=VILLAGE_HOUSE_SCALE,lx=(x-h.x)*sign/s,lz=(z-h.z)*sign/s,lr=r/s;if(Math.abs(lx)>4.4+lr||Math.abs(lz)>3.2+lr)continue;for(const seg of villageHouseSegments)if(segmentDistance(lx,lz,...seg)<lr+.025)return true;}return villageCollision.call(this,x,z,r);};
const villageBuild=MapManager.prototype.build;
MapManager.prototype.build=function(){villageBuild.call(this);
 const kept=obstacles.filter(o=>o.kind!=='trunk'||!inVillage(o.x,o.z));obstacles.length=0;buckets.clear();for(const o of kept)addObstacle(o.x,o.z,o.r,o.kind);
 if(naturalForest){naturalForest.positions=naturalForest.positions.filter(p=>!inVillage(p.x,p.z));naturalForest.update(true);}
 for(const h of villageHouses)this.assets.place('village_house',h.x,h.z,{rotation:h.r,scale:VILLAGE_HOUSE_SCALE,distance:100});
 navReady=false;buildNav();
};
const villageArea=MapManager.prototype.area;MapManager.prototype.area=function(x,z){if(inVillage(x,z)&&MapManager.inside(x,z))return '廃村';return villageArea.call(this,x,z);};
const villageRegion=pursuitRegion;pursuitRegion=function(x,z){return world.map.area(x,z)==='廃村'?'forest':villageRegion(x,z);};
const villageStart=GameManager.prototype.start;
GameManager.prototype.start=function(){villageStart.call(this);
 const fixed=[{x:74,z:-29},{x:85,z:22}];
 parts.slice(0,2).forEach((p,i)=>{Object.assign(p,fixed[i]);p.group.position.set(p.x,this.map.floor(p.x,p.z)+.42,p.z);});
 const cells=[{x:78,z:-4},{x:82,z:29}];classic.battery.items.slice(0,2).forEach((p,i)=>{Object.assign(p,cells[i]);p.group.position.set(p.x,this.map.floor(p.x,p.z)+.23,p.z);});
 updateHUD();
};

const villageFloor=MapManager.prototype.floor;
MapManager.prototype.floor=function(x,z){for(const h of villageHouses){const sign=h.r?-1:1,s=VILLAGE_HOUSE_SCALE,lx=(x-h.x)*sign/s,lz=(z-h.z)*sign/s;if((Math.abs(lx)<3.08&&lz>-2.2&&lz<1.3)||(lx>.3&&lx<2.5&&lz>=1.3&&lz<2.4))return .08*s;}return villageFloor.call(this,x,z);};

